     1→use crate::{ChainSpec, ColumnIndex, DataColumnSubnetId, EthSpec};
     2→use alloy_primitives::U256;
     3→use itertools::Itertools;
     4→use safe_arith::{ArithError, SafeArith};
     5→use std::collections::HashSet;
     6→
     7→pub type CustodyIndex = u64;
     8→
     9→#[derive(Debug)]
    10→pub enum DataColumnCustodyGroupError {
    11→    InvalidCustodyGroup(CustodyIndex),
    12→    InvalidCustodyGroupCount(u64),
    13→    ArithError(ArithError),
    14→}
    15→
    16→/// The `get_custody_groups` function is used to determine the custody groups that a node is
    17→/// assigned to.
    18→///
    19→/// Note: `get_custody_groups(node_id, x)` is a subset of `get_custody_groups(node_id, y)` if `x < y`.
    20→///
    21→/// spec: https://github.com/ethereum/consensus-specs/blob/8e0d0d48e81d6c7c5a8253ab61340f5ea5bac66a/specs/fulu/das-core.md#get_custody_groups
    22→pub fn get_custody_groups(
    23→    raw_node_id: [u8; 32],
    24→    custody_group_count: u64,
    25→    spec: &ChainSpec,
    26→) -> Result<HashSet<CustodyIndex>, DataColumnCustodyGroupError> {
    27→    if custody_group_count == spec.number_of_custody_groups {
    28→        Ok(HashSet::from_iter(0..spec.number_of_custody_groups))
    29→    } else {
    30→        get_custody_groups_ordered(raw_node_id, custody_group_count, spec)
    31→            .map(|custody_groups| custody_groups.into_iter().collect())
    32→    }
    33→}
    34→
    35→/// Returns a deterministically ordered list of custody groups assigned to a node,
    36→/// preserving the order in which they were computed during iteration.
    37→///
    38→/// # Arguments
    39→/// * `raw_node_id` - 32-byte node identifier
    40→/// * `custody_group_count` - Number of custody groups to generate
    41→/// * `spec` - Chain specification containing custody group parameters
    42→///
    43→/// # Returns
    44→/// Vector of custody group indices in computation order or error if parameters are invalid
    45→pub fn get_custody_groups_ordered(
    46→    raw_node_id: [u8; 32],
    47→    custody_group_count: u64,
    48→    spec: &ChainSpec,
    49→) -> Result<Vec<CustodyIndex>, DataColumnCustodyGroupError> {
    50→    if custody_group_count > spec.number_of_custody_groups {
    51→        return Err(DataColumnCustodyGroupError::InvalidCustodyGroupCount(
    52→            custody_group_count,
    53→        ));
    54→    }
    55→
    56→    let mut custody_groups = vec![];
    57→    let mut current_id = U256::from_be_slice(&raw_node_id);
    58→    while custody_groups.len() < custody_group_count as usize {
    59→        let mut node_id_bytes = [0u8; 32];
    60→        node_id_bytes.copy_from_slice(current_id.as_le_slice());
    61→        let hash = ethereum_hashing::hash_fixed(&node_id_bytes);
    62→        let hash_prefix: [u8; 8] = hash[0..8]
    63→            .try_into()
    64→            .expect("hash_fixed produces a 32 byte array");
    65→        let hash_prefix_u64 = u64::from_le_bytes(hash_prefix);
    66→        let custody_group = hash_prefix_u64
    67→            .safe_rem(spec.number_of_custody_groups)
    68→            .expect("spec.number_of_custody_groups must not be zero");
    69→        if !custody_groups.contains(&custody_group) {
    70→            custody_groups.push(custody_group);
    71→        }
    72→
    73→        current_id = current_id.wrapping_add(U256::from(1u64));
    74→    }
    75→
    76→    Ok(custody_groups)
    77→}
    78→
    79→/// Returns the columns that are associated with a given custody group.
    80→///
    81→/// spec: https://github.com/ethereum/consensus-specs/blob/8e0d0d48e81d6c7c5a8253ab61340f5ea5bac66a/specs/fulu/das-core.md#compute_columns_for_custody_group
    82→pub fn compute_columns_for_custody_group<E: EthSpec>(
    83→    custody_group: CustodyIndex,
    84→    spec: &ChainSpec,
    85→) -> Result<impl Iterator<Item = ColumnIndex>, DataColumnCustodyGroupError> {
    86→    let number_of_custody_groups = spec.number_of_custody_groups;
    87→    if custody_group >= number_of_custody_groups {
    88→        return Err(DataColumnCustodyGroupError::InvalidCustodyGroup(
    89→            custody_group,
    90→        ));
    91→    }
    92→
    93→    let mut columns = Vec::new();
    94→    for i in 0..spec.data_columns_per_group::<E>() {
    95→        let column = number_of_custody_groups
    96→            .safe_mul(i)
    97→            .and_then(|v| v.safe_add(custody_group))
    98→            .map_err(DataColumnCustodyGroupError::ArithError)?;
    99→        columns.push(column);
   100→    }
   101→
   102→    Ok(columns.into_iter())
   103→}
   104→
   105→pub fn compute_subnets_for_node<E: EthSpec>(
   106→    raw_node_id: [u8; 32],
   107→    custody_group_count: u64,
   108→    spec: &ChainSpec,
   109→) -> Result<HashSet<DataColumnSubnetId>, DataColumnCustodyGroupError> {
   110→    let custody_groups = get_custody_groups(raw_node_id, custody_group_count, spec)?;
   111→    let mut subnets = HashSet::new();
   112→
   113→    for custody_group in custody_groups {
   114→        let custody_group_subnets = compute_subnets_from_custody_group::<E>(custody_group, spec)?;
   115→        subnets.extend(custody_group_subnets);
   116→    }
   117→
   118→    Ok(subnets)
   119→}
   120→
   121→/// Returns the subnets that are associated with a given custody group.
   122→pub fn compute_subnets_from_custody_group<E: EthSpec>(
   123→    custody_group: CustodyIndex,
   124→    spec: &ChainSpec,
   125→) -> Result<impl Iterator<Item = DataColumnSubnetId> + '_, DataColumnCustodyGroupError> {
   126→    let result = compute_columns_for_custody_group::<E>(custody_group, spec)?
   127→        .map(|column_index| DataColumnSubnetId::from_column_index(column_index, spec))
   128→        .unique();
   129→    Ok(result)
   130→}
   131→
   132→#[cfg(test)]
   133→mod test {
   134→    use super::*;
   135→    use crate::MainnetEthSpec;
   136→
   137→    type E = MainnetEthSpec;
   138→
   139→    #[test]
   140→    fn test_compute_columns_for_custody_group() {
   141→        let mut spec = ChainSpec::mainnet();
   142→        spec.number_of_custody_groups = 64;
   143→
   144→        let columns_per_custody_group =
   145→            E::number_of_columns() / (spec.number_of_custody_groups as usize);
   146→
   147→        for custody_group in 0..spec.number_of_custody_groups {
   148→            let columns = compute_columns_for_custody_group::<E>(custody_group, &spec)
   149→                .unwrap()
   150→                .collect::<Vec<_>>();
   151→            assert_eq!(columns.len(), columns_per_custody_group);
   152→        }
   153→    }
   154→
   155→    #[test]
   156→    fn test_compute_subnets_from_custody_group() {
   157→        let mut spec = ChainSpec::mainnet();
   158→        spec.number_of_custody_groups = 64;
   159→        spec.data_column_sidecar_subnet_count = 128;
